import { createContext, useContext, useMemo, useState } from 'react'
import { Link, NavLink, Navigate, Outlet, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import {
  Activity, ArrowDownRight, ArrowLeft, ArrowRight, Award, BarChart3, Bell, BookOpen,
  Brain, Check, CheckCircle2, ChevronDown, ChevronRight, CircleAlert, ClipboardCheck,
  Clock3, Compass, FileText, GraduationCap, Home, Lightbulb, LogOut, Menu, MessageCircle,
  Plus, Search, Send, Settings, ShieldCheck, Sparkles, Target, TrendingUp, UploadCloud,
  UserRound, Users, X, Zap, LockKeyhole, Play, SlidersHorizontal, BookMarked
} from 'lucide-react'
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { topics, initialStudents, sampleCases } from './data'

const AppContext = createContext(null)
const useApp = () => useContext(AppContext)

const navMap = {
  student: [
    ['Overview', '/student/dashboard', Home], ['Explore topics', '/student/topics', Compass],
    ['AI Tutor', '/student/tutor/fractions', MessageCircle], ['Assessments', '/student/assessments', ClipboardCheck],
    ['My progress', '/student/progress', TrendingUp], ['Learning history', '/student/history', Clock3],
  ],
  teacher: [
    ['Overview', '/teacher/dashboard', Home], ['My students', '/teacher/students', Users],
    ['Misconceptions', '/teacher/misconceptions', Brain], ['Learning materials', '/teacher/materials', BookOpen],
    ['Assessments', '/teacher/assessments', ClipboardCheck],
  ],
  admin: [
    ['Overview', '/admin/dashboard', Home], ['User management', '/admin/users', Users],
    ['Content library', '/admin/content', BookOpen], ['System analytics', '/admin/analytics', BarChart3],
    ['Settings', '/settings', Settings],
  ],
}

function App() {
  const [role, setRole] = useState('student')
  const [user, setUser] = useState({ name: 'Parth', email: 'parth@example.com' })
  const [mastery, setMastery] = useState({ fractions: 68, algebra: 35, logic: 12, probability: 0 })
  const [history, setHistory] = useState([{ title: 'Comparing fractions', detail: 'Tutor session · 8 questions', date: 'Today', score: 75 }])
  const [toast, setToast] = useState('')
  const notify = (message) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }
  const value = { role, setRole, user, setUser, mastery, setMastery, history, setHistory, notify }
  return <AppContext.Provider value={value}>
    <Routes>
      <Route path="/" element={<Landing />} />
      <Route path="/about" element={<PublicInfo page="about" />} />
      <Route path="/features" element={<PublicInfo page="features" />} />
      <Route path="/contact" element={<ContactPage />} />
      <Route path="/login" element={<AuthPage mode="login" />} />
      <Route path="/signup" element={<AuthPage mode="signup" />} />
      <Route path="/forgot-password" element={<PasswordPage />} />
      <Route element={<AppShell />}>
        <Route path="/student/dashboard" element={<StudentDashboard />} />
        <Route path="/student/topics" element={<TopicsPage />} />
        <Route path="/student/lesson/:id" element={<LessonPage />} />
        <Route path="/student/tutor/:id" element={<TutorPage />} />
        <Route path="/student/diagnostic/:id" element={<DiagnosticPage />} />
        <Route path="/student/results" element={<ResultsPage />} />
        <Route path="/student/assessments" element={<StudentAssessments />} />
        <Route path="/student/progress" element={<ProgressPage />} />
        <Route path="/student/history" element={<HistoryPage />} />
        <Route path="/student/profile" element={<ProfilePage />} />
        <Route path="/settings" element={<SettingsPage />} />
        <Route path="/teacher/dashboard" element={<TeacherDashboard />} />
        <Route path="/teacher/students" element={<TeacherStudents />} />
        <Route path="/teacher/students/:id" element={<TeacherStudentDetail />} />
        <Route path="/teacher/misconceptions" element={<MisconceptionsPage />} />
        <Route path="/teacher/materials" element={<MaterialsPage />} />
        <Route path="/teacher/assessments" element={<TeacherAssessments />} />
        <Route path="/admin/dashboard" element={<AdminDashboard />} />
        <Route path="/admin/users" element={<AdminUsers />} />
        <Route path="/admin/content" element={<AdminContent />} />
        <Route path="/admin/analytics" element={<AdminAnalytics />} />
      </Route>
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
    {toast && <div role="status" className="fixed bottom-5 left-1/2 z-[100] flex -translate-x-1/2 items-center gap-2 rounded-xl bg-slate-900 px-4 py-3 text-sm font-semibold text-white shadow-xl"><CheckCircle2 size={17}/>{toast}</div>}
  </AppContext.Provider>
}

function Brand({ light = false }) {
  return <Link to="/" className={`inline-flex items-center gap-2.5 ${light ? 'text-white' : 'text-slate-900'}`}><span className="grid h-10 w-10 place-items-center rounded-xl bg-indigo-600 text-white shadow-lg shadow-indigo-200"><Brain size={22}/></span><span className="text-lg font-extrabold tracking-tight">LearnLoop <span className="text-indigo-600">AI</span></span></Link>
}
function Btn({ to, children, secondary = false, className = '', onClick, type = 'button', disabled = false }) {
  const cn = `inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-50 ${secondary ? 'border border-slate-200 bg-white text-slate-700 hover:bg-slate-50' : 'bg-indigo-600 text-white hover:bg-indigo-700'} ${className}`
  return to ? <Link to={to} className={cn}>{children}</Link> : <button type={type} onClick={onClick} disabled={disabled} className={cn}>{children}</button>
}
function Panel({ children, className = '' }) { return <div className={`rounded-2xl border border-slate-100 bg-white shadow-[0_8px_28px_rgba(24,35,59,.045)] ${className}`}>{children}</div> }
function PageHeader({ eyebrow, title, subtitle, action }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="text-[11px] font-extrabold uppercase tracking-[.18em] text-indigo-600">{eyebrow}</p>}<h1 className="mt-1 text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">{title}</h1>{subtitle && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{subtitle}</p>}</div>{action}</div>
}
function ProgressBar({ value, color = 'bg-indigo-600' }) { return <div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${color}`} style={{ width: `${Math.max(0, Math.min(100, value))}%` }}/></div> }
function StatCard({ label, value, sub, icon: Icon, tint = 'bg-indigo-50 text-indigo-600', trend }) {
  return <Panel className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-medium text-slate-500">{label}</p><p className="mt-2 text-2xl font-extrabold tracking-tight text-slate-900">{value}</p></div><span className={`rounded-xl p-2.5 ${tint}`}><Icon size={20}/></span></div><p className="mt-3 flex items-center gap-1 text-xs text-slate-500">{trend && <span className="font-bold text-emerald-600">{trend}</span>}{sub}</p></Panel>
}
function SectionTitle({ title, link, to = '#' }) { return <div className="mb-4 flex items-center justify-between gap-3"><h2 className="font-extrabold text-slate-900">{title}</h2>{link && <Link to={to} className="shrink-0 text-xs font-bold text-indigo-600 hover:text-indigo-800">{link} <ArrowRight size={13} className="inline"/></Link>}</div> }
function TopicCard({ topic, progress }) {
  const colors = { violet: 'bg-violet-100 text-violet-700', blue: 'bg-sky-100 text-sky-700', green: 'bg-emerald-100 text-emerald-700', amber: 'bg-amber-100 text-amber-700' }
  return <Panel className="flex flex-col p-5 transition hover:-translate-y-0.5 hover:shadow-lg"><div className="flex items-start justify-between"><div className={`grid h-12 w-12 place-items-center rounded-2xl text-lg font-extrabold ${colors[topic.color]}`}>{topic.symbol}</div><span className="rounded-full bg-slate-50 px-2.5 py-1 text-[10px] font-bold text-slate-500">{topic.level}</span></div><p className="mt-4 text-xs font-bold text-indigo-600">{topic.subject}</p><h3 className="mt-1 font-extrabold text-slate-900">{topic.title}</h3><p className="mt-2 flex-1 text-sm leading-6 text-slate-500">{topic.description}</p><div className="mt-5"><div className="mb-2 flex justify-between text-xs"><span className="text-slate-500">Your progress</span><b>{progress ?? topic.progress}%</b></div><ProgressBar value={progress ?? topic.progress}/></div><Btn to={`/student/lesson/${topic.id}`} secondary className="mt-5 w-full">{(progress ?? topic.progress) ? 'Continue learning' : 'Start learning'} <ArrowRight size={15}/></Btn></Panel>
}

function Landing() {
  return <div className="min-h-screen overflow-hidden bg-white">
    <header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 lg:px-8"><Brand/><nav className="hidden items-center gap-8 text-sm font-semibold text-slate-600 md:flex"><Link to="/features">Features</Link><Link to="/about">About</Link><Link to="/contact">Contact</Link></nav><div className="flex items-center gap-3"><Link to="/login" className="hidden text-sm font-bold text-slate-700 sm:block">Log in</Link><Btn to="/signup">Get started <ArrowRight size={16}/></Btn></div></header>
    <main><section className="relative mx-auto grid max-w-7xl items-center gap-12 px-5 pb-20 pt-12 lg:grid-cols-[1.05fr_.95fr] lg:px-8 lg:pb-28 lg:pt-20"><div className="absolute -left-28 top-20 h-72 w-72 rounded-full bg-violet-100/70 blur-3xl"/><div className="relative"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-indigo-100 bg-indigo-50 px-3 py-1.5 text-xs font-extrabold text-indigo-700"><Sparkles size={14}/> LEARNING THAT ADAPTS TO YOU</div><h1 className="max-w-2xl text-4xl font-black leading-[1.08] tracking-tight text-slate-900 sm:text-5xl lg:text-6xl">Understand the <span className="text-indigo-600">why</span>, not just the answer.</h1><p className="mt-6 max-w-xl text-lg leading-8 text-slate-600">An AI learning partner that helps students uncover misconceptions, practice with purpose, and build understanding that lasts.</p><div className="mt-8 flex flex-wrap gap-3"><Btn to="/signup" className="px-6 py-3">Start learning <ArrowRight size={17}/></Btn><Btn to="/features" secondary className="px-6 py-3"><Play size={16}/> See how it works</Btn></div><div className="mt-8 flex items-center gap-3 text-sm text-slate-500"><span className="grid h-9 w-9 place-items-center rounded-full bg-emerald-100 text-emerald-700"><Check size={17}/></span><span><b className="text-slate-800">Mistakes become clues.</b><br/>Every learner gets a next step.</span></div></div>
    <div className="relative mx-auto w-full max-w-xl"><div className="absolute inset-4 rounded-[2.5rem] bg-gradient-to-br from-violet-100 via-sky-50 to-emerald-100 blur-2xl"/><Panel className="relative overflow-hidden p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="font-extrabold">Your learning space</p><p className="mt-1 text-xs text-slate-500">A little progress, every day</p></div><span className="rounded-xl bg-emerald-50 p-2.5 text-emerald-700"><Activity size={20}/></span></div><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-violet-50 p-4"><BookOpen size={19} className="text-indigo-600"/><p className="mt-4 text-2xl font-extrabold">68%</p><p className="mt-1 text-xs text-slate-500">Fractions mastery</p><div className="mt-3"><ProgressBar value={68}/></div></div><div className="rounded-2xl bg-emerald-50 p-4"><Target size={19} className="text-emerald-700"/><p className="mt-4 text-2xl font-extrabold">+12%</p><p className="mt-1 text-xs text-slate-500">Weekly progress</p><div className="mt-3"><ProgressBar value={80} color="bg-emerald-500"/></div></div></div><div className="mt-4 rounded-2xl border border-slate-100 p-4"><div className="flex gap-3"><span className="h-fit rounded-xl bg-amber-50 p-2.5 text-amber-600"><Lightbulb size={20}/></span><div><p className="text-sm font-extrabold">A learning insight</p><p className="mt-1 text-xs leading-5 text-slate-500">You may be comparing denominators as whole numbers. Let's explore what happens to each piece.</p></div></div><div className="mt-4 rounded-xl bg-slate-50 px-3 py-2.5 text-xs font-bold text-slate-600">Try a visual example <ArrowRight size={13} className="inline text-indigo-600"/></div></div><div className="mt-4 flex items-center gap-2 rounded-xl bg-indigo-50 px-4 py-3 text-xs font-semibold text-indigo-800"><Sparkles size={15}/> Understanding first. Scores second.</div></Panel></div></section>
    <section className="bg-[#f7f8fc] px-5 py-16 lg:px-8"><div className="mx-auto max-w-7xl"><div className="mx-auto max-w-2xl text-center"><p className="text-xs font-extrabold uppercase tracking-[.18em] text-indigo-600">HOW IT WORKS</p><h2 className="mt-3 text-3xl font-black tracking-tight text-slate-900">From confusion to confidence</h2><p className="mt-3 text-sm leading-6 text-slate-500">Learning is a loop, not a one-time score.</p></div><div className="mt-10 grid gap-5 md:grid-cols-3">{[{n:'01',title:'Learn your way',desc:'Get clear explanations, analogies, and worked examples.',icon:BookOpen,cl:'bg-violet-100 text-violet-700'},{n:'02',title:'Find the why',desc:'Follow-up questions help distinguish a misconception from a simple slip.',icon:Brain,cl:'bg-amber-100 text-amber-700'},{n:'03',title:'Grow with evidence',desc:'Track concept-level progress and practice where it helps most.',icon:TrendingUp,cl:'bg-emerald-100 text-emerald-700'}].map(x=><Panel key={x.n} className="p-6"><div className={`grid h-12 w-12 place-items-center rounded-2xl ${x.cl}`}><x.icon size={23}/></div><p className="mt-6 text-xs font-extrabold tracking-widest text-indigo-600">{x.n}</p><h3 className="mt-2 text-lg font-extrabold">{x.title}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{x.desc}</p></Panel>)}</div></div></section>
    <section className="px-5 py-16 lg:px-8"><div className="mx-auto flex max-w-5xl flex-col items-center justify-between gap-6 rounded-3xl bg-slate-900 px-7 py-10 text-center text-white md:flex-row md:px-12 md:text-left"><div><p className="text-xs font-bold tracking-widest text-indigo-200">YOUR NEXT LEARNING LOOP STARTS HERE</p><h2 className="mt-2 text-2xl font-black sm:text-3xl">Make progress you can explain.</h2><p className="mt-2 text-sm text-slate-300">Start with a topic. Keep building from there.</p></div><Btn to="/signup" className="shrink-0 bg-white text-slate-900 hover:bg-indigo-50">Create account <ArrowRight size={16}/></Btn></div></section></main>
    <footer className="border-t border-slate-100 px-5 py-6"><div className="mx-auto flex max-w-7xl flex-col items-center justify-between gap-3 text-xs text-slate-500 sm:flex-row"><Brand/><span>© 2026 LearnLoop AI · Learning support, with teachers at the center.</span><div className="flex gap-4"><Link to="/about">About</Link><Link to="/contact">Contact</Link></div></div></footer>
  </div>
}
function PublicInfo({ page }) {
  const about = page === 'about'
  return <div className="min-h-screen bg-white"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5"><Brand/><Btn to="/signup">Get started <ArrowRight size={15}/></Btn></header><main className="mx-auto max-w-5xl px-5 py-16"><p className="text-xs font-extrabold uppercase tracking-[.18em] text-indigo-600">{about ? 'OUR APPROACH' : 'PRODUCT FEATURES'}</p><h1 className="mt-3 max-w-3xl text-4xl font-black tracking-tight text-slate-900">{about ? 'Learning that starts with understanding.' : 'Tools designed around the way students learn.'}</h1><p className="mt-5 max-w-3xl text-lg leading-8 text-slate-600">LearnLoop AI helps students move beyond right and wrong answers. It explores their reasoning, suggests likely misconceptions, and adapts practice based on evidence over time.</p><div className="mt-10 grid gap-5 md:grid-cols-3">{[{icon:Brain,title:'Explainable diagnosis',body:'A suspected misconception is a hypothesis to test, not a label to assign.'},{icon:BookOpen,title:'Grounded tutoring',body:'Clear explanations and practice should be based on reviewed learning material.'},{icon:GraduationCap,title:'Teacher oversight',body:'Teachers can review evidence, correct AI suggestions, and guide next steps.'}].map(x=><Panel key={x.title} className="p-6"><x.icon className="text-indigo-600" size={25}/><h3 className="mt-4 font-extrabold">{x.title}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{x.body}</p></Panel>)}</div><Btn to="/signup" className="mt-9">Try the demo <ArrowRight size={15}/></Btn></main></div>
}
function ContactPage() {
  const { notify } = useApp()
  return <div className="min-h-screen bg-white"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5"><Brand/><Btn to="/login" secondary>Log in</Btn></header><main className="mx-auto max-w-2xl px-5 py-14"><p className="text-xs font-extrabold uppercase tracking-widest text-indigo-600">CONTACT</p><h1 className="mt-3 text-4xl font-black">Let's talk learning.</h1><p className="mt-3 text-sm leading-6 text-slate-500">Send the team a note. This form is a frontend demo until an email or backend service is connected.</p><form className="mt-8 space-y-4" onSubmit={e=>{e.preventDefault();notify('Message captured in demo mode')}}><label className="block text-sm font-bold">Your name<input required className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-indigo-500" placeholder="Name"/></label><label className="block text-sm font-bold">Email address<input required type="email" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-indigo-500" placeholder="you@example.com"/></label><label className="block text-sm font-bold">Message<textarea required rows="5" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-indigo-500" placeholder="How can we help?"/></label><Btn type="submit">Send message <ArrowRight size={15}/></Btn></form></main></div>
}
function AuthPage({ mode }) {
  const signup = mode === 'signup'
  const { setRole, setUser, notify } = useApp()
  const [name,setName] = useState('')
  const [email,setEmail] = useState('')
  const [password,setPassword] = useState('')
  const [role,setRoleChoice] = useState('student')
  const nav = useNavigate()
  const submit = e => { e.preventDefault(); setRole(role); setUser({name:name.trim() || (role==='teacher'?'Teacher':role==='admin'?'Admin':'Parth'),email}); notify('Demo session started'); nav(role==='student'?'/student/dashboard':`/${role}/dashboard`) }
  return <div className="grid min-h-screen bg-white lg:grid-cols-2"><div className="flex items-center justify-center px-5 py-12"><div className="w-full max-w-md"><Brand/><div className="mt-10"><p className="text-xs font-extrabold uppercase tracking-widest text-indigo-600">{signup?'START LEARNING':'WELCOME BACK'}</p><h1 className="mt-3 text-3xl font-black text-slate-900">{signup?'Create your account':'Welcome back'}</h1><p className="mt-2 text-sm text-slate-500">{signup?'Build understanding one learning loop at a time.':'Pick up where your curiosity left off.'}</p></div><form onSubmit={submit} className="mt-8 space-y-4">{signup&&<label className="block text-sm font-bold">Full name<input className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 font-normal outline-none focus:border-indigo-500" value={name} onChange={e=>setName(e.target.value)} placeholder="Your name" required/></label>}<label className="block text-sm font-bold">Email address<input type="email" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 font-normal outline-none focus:border-indigo-500" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required/></label><label className="block text-sm font-bold">Password<input type="password" minLength="6" className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 font-normal outline-none focus:border-indigo-500" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 6 characters" required/></label><label className="block text-sm font-bold">Continue as<select className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 font-normal outline-none focus:border-indigo-500" value={role} onChange={e=>setRoleChoice(e.target.value)}><option value="student">Student</option><option value="teacher">Teacher</option><option value="admin">Administrator (demo)</option></select></label>{!signup&&<div className="text-right"><Link to="/forgot-password" className="text-sm font-bold text-indigo-600">Forgot password?</Link></div>}<Btn type="submit" className="w-full py-3">{signup?'Create account':'Log in'} <ArrowRight size={16}/></Btn><p className="text-center text-sm text-slate-500">{signup?'Already have an account?':'New to LearnLoop AI?'} <Link to={signup?'/login':'/signup'} className="font-extrabold text-indigo-600">{signup?'Log in':'Sign up'}</Link></p></form><p className="mt-8 text-center text-xs leading-5 text-slate-400">Demo only: authentication is not connected to a secure backend yet.</p></div></div><div className="relative hidden overflow-hidden bg-gradient-to-br from-indigo-700 via-indigo-600 to-violet-500 p-12 text-white lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-20 -top-20 h-96 w-96 rounded-full border-[60px] border-white/10"/><Brand light/><div className="relative max-w-lg"><div className="mb-6 grid h-14 w-14 place-items-center rounded-2xl bg-white/15"><Sparkles size={28}/></div><h2 className="text-4xl font-black leading-tight">A wrong answer can be the start of a breakthrough.</h2><p className="mt-5 leading-7 text-indigo-100">LearnLoop helps you discover what you understand, what needs another look, and what to try next.</p><div className="mt-8 rounded-2xl border border-white/20 bg-white/10 p-5"><p className="text-sm font-bold">Instead of just saying “try again”</p><p className="mt-2 text-sm leading-6 text-indigo-100">“Let's explore how the size of each piece changes when we divide the same whole into more parts.”</p></div></div><p className="relative text-xs text-indigo-100">Adaptive support. Human guidance. Meaningful progress.</p></div></div>
}
function PasswordPage() {
  const { notify } = useApp()
  return <div className="flex min-h-screen items-center justify-center px-5"><Panel className="w-full max-w-md p-7"><Brand/><h1 className="mt-8 text-2xl font-black">Reset your password</h1><p className="mt-2 text-sm text-slate-500">Enter your email to request reset instructions.</p><form onSubmit={e=>{e.preventDefault();notify('Demo: connect password reset to backend')}} className="mt-6 space-y-4"><input type="email" required className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm" placeholder="you@example.com"/><Btn type="submit" className="w-full">Send instructions</Btn></form><Link to="/login" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-indigo-600"><ArrowLeft size={15}/> Back to login</Link></Panel></div>
}

function AppShell() {
  const { role, setRole, user, notify } = useApp()
  const [mobileOpen,setMobileOpen] = useState(false)
  const nav = useNavigate()
  const location = useLocation()
  const navItems = navMap[role] || navMap.student
  const title = navItems.find(n=>location.pathname===n[1])?.[0] || ({'/student/results':'Assessment results','/student/profile':'My profile','/teacher/misconceptions':'Misconception review','/teacher/materials':'Learning materials','/teacher/assessments':'Assessments','/admin/content':'Content library','/admin/analytics':'System analytics','/settings':'Settings'}[location.pathname] || 'Learning workspace')
  const switchRole = e => { const r=e.target.value; setRole(r); nav(r==='student'?'/student/dashboard':`/${r}/dashboard`); setMobileOpen(false) }
  return <div className="min-h-screen bg-[#f7f8fc]">
    {mobileOpen&&<button aria-label="Close navigation" onClick={()=>setMobileOpen(false)} className="fixed inset-0 z-40 bg-slate-950/30 lg:hidden"/>}
    <aside className={`fixed inset-y-0 left-0 z-50 flex w-64 flex-col border-r border-slate-100 bg-white px-4 py-5 transition-transform lg:translate-x-0 ${mobileOpen?'translate-x-0':'-translate-x-full'}`}><div className="flex items-center justify-between px-1"><Brand/><button onClick={()=>setMobileOpen(false)} className="rounded-lg p-2 text-slate-400 lg:hidden"><X size={18}/></button></div><div className="mt-8 rounded-2xl bg-slate-50 p-3"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-violet-100 font-extrabold text-indigo-700">{(user.name||'P').slice(0,1).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-extrabold">{user.name}</p><p className="text-xs capitalize text-slate-500">{role} workspace</p></div></div><select aria-label="Switch demo role" value={role} onChange={switchRole} className="mt-3 w-full rounded-lg border border-slate-200 bg-white px-2 py-2 text-xs font-bold text-slate-600"><option value="student">Student demo</option><option value="teacher">Teacher demo</option><option value="admin">Admin demo</option></select></div><p className="mb-3 mt-8 px-3 text-[10px] font-extrabold uppercase tracking-[.18em] text-slate-400">Workspace</p><nav className="space-y-1">{navItems.map(([label,to,Icon])=><NavLink key={to} to={to} onClick={()=>setMobileOpen(false)} className={({isActive})=>`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-bold transition ${isActive?'bg-violet-50 text-indigo-700':'text-slate-600 hover:bg-slate-50'}`}><Icon size={18}/>{label}{label==='Misconceptions'&&<span className="ml-auto rounded-full bg-amber-100 px-2 py-0.5 text-[10px] text-amber-800">3</span>}</NavLink>)}</nav><div className="mt-auto"><div className="rounded-2xl bg-gradient-to-br from-indigo-50 to-violet-50 p-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white text-indigo-600"><Lightbulb size={18}/></span><p className="mt-3 text-sm font-extrabold">Need a hand?</p><p className="mt-1 text-xs leading-5 text-slate-500">Learning is a process. Ask for help whenever you need it.</p><button onClick={()=>notify('Help center demo opened')} className="mt-3 text-xs font-extrabold text-indigo-600">Visit help center <ArrowRight size={12} className="inline"/></button></div><button onClick={()=>{setRole('student');nav('/')}} className="mt-4 flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-bold text-slate-500 hover:bg-slate-50"><LogOut size={17}/> Exit workspace</button></div></aside>
    <div className="min-h-screen lg:pl-64"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-slate-100 bg-white/90 px-4 backdrop-blur sm:px-7"><div className="flex items-center gap-3"><button onClick={()=>setMobileOpen(true)} className="rounded-lg p-2 text-slate-600 lg:hidden"><Menu size={20}/></button><div><p className="text-sm font-extrabold text-slate-900">{title}</p><p className="hidden text-xs text-slate-500 sm:block">Your learning, one loop at a time</p></div></div><div className="flex items-center gap-2 sm:gap-4"><button onClick={()=>notify('You are all caught up!')} aria-label="Notifications" className="relative rounded-xl border border-slate-100 p-2.5 text-slate-500 hover:bg-slate-50"><Bell size={17}/><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-rose-500"/></button><Link to="/student/profile" className="flex items-center gap-2 rounded-xl p-1.5 hover:bg-slate-50"><div className="grid h-9 w-9 place-items-center rounded-xl bg-indigo-100 text-sm font-extrabold text-indigo-700">{(user.name||'P').slice(0,1).toUpperCase()}</div><div className="hidden text-left sm:block"><p className="text-xs font-extrabold">{user.name}</p><p className="text-[10px] capitalize text-slate-500">{role}</p></div></Link></div></header><main className="mx-auto max-w-[1500px] p-4 sm:p-7"><Outlet/></main></div>
  </div>
}

