  const filtered = topics.filter(t=>(t.title+' '+t.description).toLowerCase().includes(query.toLowerCase())&&(subject==='All subjects'||t.subject===subject))
  return <><PageHeader eyebrow="LEARNING LIBRARY" title="Explore topics" subtitle="Choose a topic, learn the foundations, and practice with adaptive guidance."/><Panel className="mb-6 flex flex-col gap-3 p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 text-slate-400" size={17}/><input className="w-full rounded-xl border border-slate-200 py-3 pl-10 pr-4 text-sm outline-none focus:border-indigo-500" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search topics or concepts..."/></div><select className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm sm:w-56" value={subject} onChange={e=>setSubject(e.target.value)}><option>All subjects</option><option>Mathematics</option><option>Computer Science</option></select></Panel><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(t=><TopicCard key={t.id} topic={t}/>)}</div>{!filtered.length&&<EmptyState title="No topics found" text="Try another search term or subject filter."/>}</>
